CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_internationalpayments]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_internationalpayments]
	(
		[apuk_contactid],
		[apuk_contactid_entitytype],
		[apuk_contactidname],
		[apuk_contactidyominame],
		[apuk_country],
		[apuk_dateprocessed],
		[apuk_internationalpaymentsid],
		[apuk_localgroup],
		[apuk_localgroupid],
		[apuk_localgroupid_entitytype],
		[apuk_localgroupidname],
		[apuk_localincomeamount],
		[apuk_localincomeamount_base],
		[apuk_membercurrency],
		[apuk_membername],
		[apuk_membernumber],
		[apuk_name],
		[apuk_paymentamount],
		[apuk_paymentamount_base],
		[apuk_paymentdate],
		[apuk_paymentreference],
		[apuk_paymenttype],
		[apuk_processedbyslteam],
		[apuk_quote],
		[apuk_quote_entitytype],
		[apuk_quotename],
		[apuk_ukincomeamount],
		[apuk_ukincomeamount_base],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_contactid],
		stg.[apuk_contactid_entitytype],
		stg.[apuk_contactidname],
		stg.[apuk_contactidyominame],
		stg.[apuk_country],
		stg.[apuk_dateprocessed],
		stg.[apuk_internationalpaymentsid],
		stg.[apuk_localgroup],
		stg.[apuk_localgroupid],
		stg.[apuk_localgroupid_entitytype],
		stg.[apuk_localgroupidname],
		stg.[apuk_localincomeamount],
		stg.[apuk_localincomeamount_base],
		stg.[apuk_membercurrency],
		stg.[apuk_membername],
		stg.[apuk_membernumber],
		stg.[apuk_name],
		stg.[apuk_paymentamount],
		stg.[apuk_paymentamount_base],
		stg.[apuk_paymentdate],
		stg.[apuk_paymentreference],
		stg.[apuk_paymenttype],
		stg.[apuk_processedbyslteam],
		stg.[apuk_quote],
		stg.[apuk_quote_entitytype],
		stg.[apuk_quotename],
		stg.[apuk_ukincomeamount],
		stg.[apuk_ukincomeamount_base],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_internationalpayments] stg
		LEFT JOIN [synapse_ce].[apuk_internationalpayments] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
